const update = $input.item.json;
const message = update.message || update.callback_query?.message;
const callback = update.callback_query?.data;
const text = update.message?.text || '';
const chatId = message.chat.id;

let response = { chatId, route: 'menu' };

if (text === '/start' || text === '/menu' || callback === 'menu') {
  response.text = '🏠 *Парсер аренды недвижимости*\n\n✨ Автоматический поиск квартир\n🔍 Мониторинг каждые 3 минуты\n📸 Фото + цена + адрес + телефон\n🤖 AI консультант по аренде\n\n*Платформы:*\n🔵 Cian.ru\n🔴 Yandex.Realty\n🟢 Avito.ru';
  response.keyboard = {
    inline_keyboard: [
      [{text: '🏙️ Выбрать город', callback_data: 'select_city'}],
      [{text: '🔍 Выбрать платформы', callback_data: 'select_platforms'}],
      [{text: '⚙️ Настройки', callback_data: 'settings'}],
      [{text: '🤖 AI Консультант', callback_data: 'ai_help'}],
      [{text: '❓ FAQ', callback_data: 'faq'}, {text: '✍️ Отзыв', callback_data: 'review'}]
    ]
  };
}
else if (callback === 'select_city') {
  response.text = '🏙️ *Выбор города*\n\nВыберите город для парсинга:';
  response.keyboard = {
    inline_keyboard: [
      [{text: 'Москва', callback_data: 'city_москва'}],
      [{text: 'Санкт-Петербург', callback_data: 'city_санкт-петербург'}],
      [{text: 'Благовещенск', callback_data: 'city_благовещенск'}],
      [{text: 'Екатеринбург', callback_data: 'city_екатеринбург'}],
      [{text: 'Новосибирск', callback_data: 'city_новосибирск'}],
      [{text: 'Казань', callback_data: 'city_казань'}],
      [{text: '🔙 Назад', callback_data: 'menu'}]
    ]
  };
}
else if (callback && callback.startsWith('city_')) {
  const city = callback.replace('city_', '');
  $getWorkflowStaticData('node').selectedCity = city;
  response.text = `✅ Город изменен на: *${city}*\n\nТеперь парсер будет искать квартиры в этом городе.`;
  response.keyboard = {
    inline_keyboard: [[{text: '🏠 Главное меню', callback_data: 'menu'}]]
  };
}
else if (callback === 'select_platforms') {
  const platforms = $getWorkflowStaticData('node').selectedPlatforms || ['cian', 'yandex', 'avito'];
  const checks = {
    cian: platforms.includes('cian') ? '✅' : '☐',
    yandex: platforms.includes('yandex') ? '✅' : '☐',
    avito: platforms.includes('avito') ? '✅' : '☐'
  };
  response.text = `🔍 *Выбор платформ*\n\n${checks.cian} Cian.ru\n${checks.yandex} Yandex.Realty\n${checks.avito} Avito.ru\n\nВыберите платформы для парсинга:`;
  response.keyboard = {
    inline_keyboard: [
      [{text: `${checks.cian} Cian`, callback_data: 'toggle_cian'}],
      [{text: `${checks.yandex} Yandex`, callback_data: 'toggle_yandex'}],
      [{text: `${checks.avito} Avito`, callback_data: 'toggle_avito'}],
      [{text: '✅ Все', callback_data: 'platforms_all'}, {text: '❌ Сбросить', callback_data: 'platforms_none'}],
      [{text: '🔙 Назад', callback_data: 'menu'}]
    ]
  };
}
else if (callback && callback.startsWith('toggle_')) {
  const platform = callback.replace('toggle_', '');
  let platforms = $getWorkflowStaticData('node').selectedPlatforms || ['cian', 'yandex', 'avito'];
  if (platforms.includes(platform)) {
    platforms = platforms.filter(p => p !== platform);
  } else {
    platforms.push(platform);
  }
  $getWorkflowStaticData('node').selectedPlatforms = platforms;
  response.text = '✅ Настройки сохранены!';
  response.keyboard = {
    inline_keyboard: [[{text: '🔍 Выбрать платформы', callback_data: 'select_platforms'}], [{text: '🏠 Главное меню', callback_data: 'menu'}]]
  };
}
else if (callback === 'platforms_all') {
  $getWorkflowStaticData('node').selectedPlatforms = ['cian', 'yandex', 'avito'];
  response.text = '✅ Выбраны все платформы!';
  response.keyboard = {
    inline_keyboard: [[{text: '🏠 Главное меню', callback_data: 'menu'}]]
  };
}
else if (callback === 'platforms_none') {
  $getWorkflowStaticData('node').selectedPlatforms = [];
  response.text = '❌ Все платформы отключены!';
  response.keyboard = {
    inline_keyboard: [[{text: '🔍 Выбрать платформы', callback_data: 'select_platforms'}]]
  };
}
else if (callback === 'settings') {
  const city = $getWorkflowStaticData('node').selectedCity || 'москва';
  const platforms = $getWorkflowStaticData('node').selectedPlatforms || ['cian', 'yandex', 'avito'];
  response.text = `⚙️ *Текущие настройки*\n\n🏙️ Город: ${city}\n🔍 Платформы: ${platforms.join(', ')}\n⏰ Интервал: каждые 3 минуты\n📊 Макс. страниц: 5\n\n*Статус парсера:* Активен ✅`;
  response.keyboard = {
    inline_keyboard: [
      [{text: '🏙️ Сменить город', callback_data: 'select_city'}],
      [{text: '🔍 Сменить платформы', callback_data: 'select_platforms'}],
      [{text: '🔙 Назад', callback_data: 'menu'}]
    ]
  };
}
else if (callback === 'ai_help') {
  response.text = '🤖 *AI Консультант*\n\nЗадайте любой вопрос об аренде квартир!\n\nПримеры:\n• Как проверить квартиру перед арендой?\n• На что обратить внимание при осмотре?\n• Какие документы нужны?\n• Как торговаться с арендодателем?';
  response.keyboard = {
    inline_keyboard: [[{text: '🔙 Назад', callback_data: 'menu'}]]
  };
  response.route = 'menu';
}
else if (callback === 'faq') {
  response.text = '❓ *Частые вопросы*\n\n*Как работает бот?*\nАвтоматический парсинг Cian, Yandex, Avito каждые 3 минуты.\n\n*Что включено?*\nФото, цена, адрес, телефон, автонабор.\n\n*Дублируются объявления?*\nНет! Встроенная дедупликация.\n\n*Какие города?*\nЛюбые города России.\n\n*Сколько платформ?*\n3 платформы одновременно!';
  response.keyboard = {
    inline_keyboard: [[{text: '📞 Поддержка', callback_data: 'support'}], [{text: '🔙 Назад', callback_data: 'menu'}]]
  };
}
else if (callback === 'review') {
  response.text = '✍️ *Оставить отзыв*\n\nОцените работу бота:';
  response.keyboard = {
    inline_keyboard: [
      [{text: '⭐⭐⭐⭐⭐ Отлично', callback_data: 'rate_5'}],
      [{text: '⭐⭐⭐⭐ Хорошо', callback_data: 'rate_4'}],
      [{text: '⭐⭐⭐ Нормально', callback_data: 'rate_3'}],
      [{text: '🔙 Назад', callback_data: 'menu'}]
    ]
  };
}
else if (callback && callback.startsWith('rate_')) {
  response.text = '💖 Спасибо за отзыв! Мы ценим ваше мнение.';
  response.keyboard = {
    inline_keyboard: [[{text: '🏠 Главное меню', callback_data: 'menu'}]]
  };
}
else if (callback === 'support') {
  response.text = '📞 *Поддержка*\n\nПо всем вопросам: @your_support\nEmail: support@rental.ru';
  response.keyboard = {
    inline_keyboard: [[{text: '🔙 Назад', callback_data: 'menu'}]]
  };
}
else if (!text.startsWith('/') && text.length > 5) {
  response.text = text;
  response.route = 'ai';
}
else {
  response.text = 'Используйте /menu для навигации';
  response.keyboard = {
    inline_keyboard: [[{text: '🏠 Меню', callback_data: 'menu'}]]
  };
}

return { json: response };

