const response = $input.first().json;
const listings = Array.isArray(response) ? response : (response.listings || []);

if (!listings || listings.length === 0) {
  console.log('No unsent listings');
  return [];
}

console.log(`Found ${listings.length} unsent listings`);

return listings.map(listing => ({ json: listing }));

const listing = $input.item.json;

const platformEmoji = {
  cian: '🔵',
  yandex: '🔴',
  avito: '🟢'
};

const platformName = {
  cian: 'Cian',
  yandex: 'Yandex',
  avito: 'Avito'
};

const emoji = platformEmoji[listing.platform] || '⚪';
const name = platformName[listing.platform] || listing.platform;

const rooms = listing.rooms === 0 ? 'Студия' : (listing.rooms ? `${listing.rooms}-комн` : '');
const price = listing.price ? `${Math.round(listing.price).toLocaleString('ru-RU')} ₽/мес` : 'Уточняйте';

let caption = `${emoji} *${name}*\n\n`;
caption += `*${listing.title || 'Квартира'}*\n\n`;
caption += `💰 ${price}\n`;

if (rooms || listing.area) {
  let parts = [];
  if (rooms) parts.push(`🏠 ${rooms}`);
  if (listing.area) parts.push(`${listing.area} м²`);
  caption += parts.join(', ') + '\n';
}

if (listing.address) {
  caption += `📍 ${listing.address}\n`;
}

if (listing.phone) {
  caption += `📞 \`${listing.phone}\`\n`;
}

caption += `\n🔗 [Открыть объявление](${listing.url})`;

// Получаем chat_ids из Static Data или env
const chatIds = $getWorkflowStaticData('global').subscribedUsers || ['7984101063'];

return {
  json: {
    ...listing,
    caption: caption,
    chatIds: chatIds,
    photo: listing.image || 'https://via.placeholder.com/600x400/4A90E2/ffffff?text=Квартира'
  }
};
